/** A plan on a person: an amount claimed every N days from a start date to an end date (yyyy-mm-dd). */
export interface PlanView {
  id: number;
  personId: number;
  /** The amount with two decimals, e.g. "12.50". */
  amount: string;
  start: string;
  every: number;
  end: string;
  /** How many claims the plan has made so far. */
  generated: number;
}

/** A plan as typed on the form. */
export interface PlanForm {
  amount: string;
  start: string;
  every: string;
  end: string;
}

/** What a generate made: how many claims, those claims in the order made, and the sheet's plans after it. */
export interface GeneratedView {
  count: number;
